import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"西溪易说卷五","description":"西溪易说 - 西溪易说卷五","frontmatter":{"title":"西溪易说卷五","description":"西溪易说 - 西溪易说卷五"},"headers":[],"relativePath":"zh/classics/xixi/006.md","filePath":"zh/classics/xixi/006.md"}'),i={name:"zh/classics/xixi/006.md"};function r(c,p,_,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="西溪易说卷五" tabindex="-1">西溪易说卷五 <a class="header-anchor" href="#西溪易说卷五" aria-label="Permalink to “西溪易说卷五”">​</a></h1><p>钦定四库全书</p><p>宋李过撰</p><p>䷒ 兑下坤上</p><p>「临」：</p><p>「临」：元、亨、利、贞。至于八月有凶。彖曰：「临」，刚浸而长，说而顺，刚中而应，大亨以正，天之道也。至于「八月有凶」，消不久也。二阳生卦乃为「临」。「临」，君临之道也。阳生于二，何以为君道也？当看乾卦二爻「见龙在田」，天下已有「利见大人」之意。盖二虽非君位，君德已施普，而天下已文明，此二阳生，所以为君临之道也。二爻曰「咸临」，君位在五，而感道已在二故也，故曰「临：临，元、亨、利、贞」。一阳生复，二阳生临，「刚浸而长」也。德说而顺，二刚得中，天下感应，阳道大亨而正，天运方来，理之必盛也。至于八月有凶，阴阳之道，消长不穷。二阳方生，圣人已为之戒，防患之早也。盖二阳生临，三阳生泰，四阳生壮，五阳生夬，六阳纯乾，</p><p>一阴生姤，二阴生遁，三阴生否、四阴生观。是八月也，二阳已消而在上矣。临卦二阳生，方来之势也；观卦二阳消，已去之势也。圣人于阳气方生之时，预为阳气已消之戒，故彖曰「消不久也」。圣人之虑远矣。</p><p>象曰：泽上有地，「临」；君子以教思无穷，容保民无疆。泽所以聚水也，泽水更有地，尽有可容处。临下之道当以宽，王者必有容天下之量，故君子体临之象，教思必无穷，保民必无疆也。「教思无穷」，体「兑」之「说」；「保民无疆」，体「坤」之「厚」。</p><p>初九，咸临，贞吉。象曰：「咸临贞吉」，志行正也。</p><p>初九一阳初生，已有感意。临人之道，善意方萌，已感之矣。感人以善，临之正也，故曰「咸临贞吉」，象曰云云。</p><p>九二，咸临，吉，无不利。象曰：「咸临吉无不利」，未顺命也。二阳生地上，天下文明矣，故曰「咸临吉无不利」，象曰「未顺命也」。既曰「吉无不利」，何故「未顺命」？盖二阳方生，天下已感；五正君位，方能制命。顺命在五，而感道在二，感人之道，当感之于未顺命之先，犹之「乾为飞龙」，在五而二已利见也，故曰「未顺命也」。</p><p>六三，甘临，无攸利；既忧之，无咎。象曰：「甘临」，位不当也；「既忧之」，咎不长也。</p><p>三居兑上，说体，「兑为口舌」，以甘言临人者也，故「无攸利」。然三爻多忧，故言语不足以感人而危之，可「无咎」。象曰：「位不当也」，言所居不正也；「既忧之」，咎不长也。既忧其非，则得所以临人之道矣，故「咎不长」。</p><p>六四，至临，无咎。象曰：「至临无咎」，位当也。</p><p>卦之至于八月有凶，数月至八，四阴生而二阳消，正此爻，故曰「至临」。知患之至而能豫防之，临道之善也，故「无咎」。象曰「位当也」，谓四阴之生，正当此位也。</p><p>六五，知临，大君之宜，吉。象曰：「大君之宜」，行中之谓也。五君位，君道利明不利幽，故知临为得宜。然临人之道，必以宽简，何至于用知？五纯坤体，含弘光大之君也，故惟宽大之君，然后可以用知，否则苛察矣。故曰「知临，大君之宜，吉」。言宽大之君，则宜用知而吉也。象曰：行中之谓也。言中则不至于过也。</p><p>上六：敦临，吉，无咎。象曰：「敦临」之吉，志在内也。</p><p>上六居坤之极，泽上有地，即此爻也，故曰「敦临」。言其德厚无疆也，故「吉，无咎」。象曰「志在内也」，言志在保民，其中足以有容也。䷓ 坤下巽上</p><p>观，</p><p>观盥而不荐，有孚颙若。彖曰：大观在上，顺而巽，中正以观天下。</p><p>「观盥而不荐，有孚颙若」，下观而化也。观天之神道，而四时不忒。圣人以神道设教，而天下服矣。</p><p>二阳在上，为四阴所观，天下观化于上之象也。阳尊君位，以临四阴，履顺而巽，居中履正，以观天下，故五为观之主，大观在上者也。四阴在下，观化于下者也。在上则为君子之观，在下则为小人之观。君子，为人所观者也；小人，观于人者也。曰</p><p>「观，盥而不荐，冇孚颙若」。颙，仰望也。下仰化于上，要以诚感人之荐鬼神也。当盥手而执匕鬯之时，诚意专一；至荐食之后，诚意少衰。故化人之道，当观于方盥之时，而不观于既荐之后也。天五方之民异性，而千里、百里不同风俗，然圣人设教，自有不疾而速、不行而至者。观感之机，不待家喻而户晓也。意诚于此而民孚于彼，要之，吾身自有本也。故曰：「观天之神道，而四时不忒。」圣人以神道设教而天下服，是则大观之君所为也。</p><p>象曰：风行地上，「观」。先王以省方观民设教。</p><p>风行地上，无远近高下，莫不旁周而徧及。圣人所以为省方之礼，以观民俗而设教化也。</p><p>初六：童观，小人无咎，君子吝。象曰：「初六童观」，小人道也。以柔居最下，去二阳远，非能观者，童子之观也。卦以上体为观之善，故君子处此则吝。小人，观于人者也，其道固如此也。六二：𬮭观，利女贞。象曰：「𬮭观女贞」，亦可丑也。</p><p>以柔居内卦之中，处下体而不能上进，帘视壁听，女子之观也。</p><p>六三，观我生，进退。象曰：「观我生进退」，未失道也。</p><p>三处上体近，然未离乎下，进则为君子之观，退则同小人之观，但观其所取也。象曰：未失道也。处下卦之上，去𬮭童观为有间矣，进退尚未决，故「未失道」也。</p><p>六四，观国之光，利用宾于王。象曰：「观国之光」，尚宾也。四居群阴之上，进居上体而切近九五，诸侯宾于天子，观光于上，国之象也。庭实旅百，奉之以玉帛，礼之至也。进得所观而受殊礼也，处观之善者也。</p><p>九五，观我生，君子无咎。象曰：「观我生」，观民也。</p><p>五大观在上，居中履正以观天下，为观之主，君子之观也。一人之身，天下风俗之所系，笑颦以下，皆观感之枢机也，故不必观化于天下，而常观化于己，观我生而无咎，则天下无咎矣。象曰：「观我生」，观民也。「观我生」，乃所以观民也，盖君民无二本也。</p><p>上九：观其生，君子无咎。象曰：「观其生」，志未平也。</p><p>五观我生矣，上又观其生者，合己与物而观之也，是亦君子之观，故无咎。然以卦中六爻观之，初六童观，小人之观也，非观之善。二曰「𬮭观」，女子之观也，非观之善。三曰进退去就，特未决也，亦非观之善。己以贤德在上，为天下之观，而下体皆未善，是天下未能观化，道德未能一，风俗未能同也，故象曰「志未平也」。䷔ 震下离上 噬嗑，</p><p>噬嗑亨。利用狱。彖曰：颐中有物，曰「噬嗑」。噬嗑而亨，刚柔分，动而明，雷电合而章。柔得中而上行，虽不当位，「利用狱」也。</p><p>「噬」，啮也。「嗑」，合也。彖谓「颐中有物，曰噬嗑」。颐中四阴，上下二阳，如人之颐颔焉。今「噬嗑」九四，一阳梗其中，是颐中为物所梗。「颐中有物」，必噬而嗑之，乃亨通也，故卦名「噬嗑」。震下离上：震为雷，离为电。天地生万物，有为造化之梗者，必用雷电以击抟之。圣人之治天下，有为万民之梗者，必用刑狱以断制之。故「噬嗑」所以去颐中之梗者，雷电所以去天地之梗，刑狱所以去天下之梗也。卦辞曰「利用狱」，言有小人为天下之梗者，宜用刑狱以去之也。六爻只言用狱之道。彖：颐中有物曰「噬嗑」。「噬嗑」而亨，言噬而「嗑」，乃「亨」也。刚柔分六爻，刚与柔等也。「动而明」，震体动而离体明也。「雷电合而章」。雷之击物，必与电合，然后成章也。人之颐中，自有雷电，齿刚而舌柔，雷之击抟，必与电合；齿之噬嗑，必与舌俱，然后成章也。「柔得中而上行」。谓六五得中而居上，以柔居五，虽不当位，然后得治狱之道也。盖圣人用刑，出不得已，以柔治狱，圣人之仁也。此义见在五爻。</p><p>象曰：「雷电」，「噬嗑」。先王以明罚𠡠法。</p><p>天地去万物之梗，必以雷电，犹去颐中之梗，必以「噬嗑」。先王体之，有小人之梗，必用刑狱，故体「离」之照以明罚，体「震」之威以𠡠法。</p><p>初九，屦校灭趾，无咎。象曰：「屦校灭趾」，不行也。</p><p>六爻皆说用狱，初为恶之始，上为恶之终，中四爻同颐中之物，六爻节目如此。初最下，小人之为恶者也，为恶之始，姑少惩之，以屦校而灭其趾，令不得行而听其改过也，故因「灭趾」而「无咎」。周礼：「坐之圜土，纳之嘉石」，乃其义也。系辞曰：「小人不耻不仁，不畏不义，不见利不劝，不威不惩。」小惩而大诫，此小人之福也。易曰：「屦校灭趾，无咎。」</p><p>六二，噬肤灭鼻，无咎。象曰：「噬肤灭鼻」，乘刚也。</p><p>以六爻之位言之，五，君位也，为治狱之主；四，大臣位也，为治狱之卿；又其下也，为治狱之吏。颐中之物最大，乾胏是乾胏，乾肉之冇骨者，最难噬也。六二体柔，以噬肤之道噬之，自伤其鼻，然亦「无咎」也。治狱者也，故咎不在己。象曰「乘刚也」，谓九四刚物也，己以柔道乘而噬也，故伤也。六三，噬腊肉，遇毒，小吝，无咎。象曰：「遇毒」，位不当也。六三体亦柔，见二之伤也，以噬腊肉之道噬之，亦遇其毒，盖不虞乾胏之有骨也，遂为所毒，虽小吝，亦无咎，意在去恶己，则何咎！象曰「位不当也」，以三体柔也。</p><p>九四，噬乾胏，得金矢，利艰贞，吉。象曰：「利艰贞吉」，未光也。颐中之梗，正在此爻。九四近君，治狱之卿也。诸爻以柔噬，九四独以刚噬。「乾胏」，乾肉之有骨者。此小人难噬，正如「乾胏」。而九四体刚，以噬乾胏之道噬之，遂得其情，故曰「噬乾胏，得金矢」。古者司寇以两剂禁民狱，入钩金，然后听之，既得其情，则得钩金；以两造禁民讼，入束矢，然后听之，既得其情，则得束矢。曰「得金矢」，谓得其情也。然不敢以为能也，宜以「艰贞」之道自守，则「吉」。象曰「未光也」，盖刑期于无刑，治狱者之职也。今犹有小人之梗，非治狱之善也。古人治狱如得其情，则哀矜而勿喜，盖谓此也。</p><p>六五：噬乾肉，得黄金，贞厉，无咎。象曰：「贞厉无咎」，得当也。六五君位，所谓「柔得中而上行」者也。九四「噬嗑」，既得其情矣，以狱之成告于六五。五，柔主也，依前以噬乾肉之道噬之。「乾肉」，无骨者也，盖以柔噬之也。于是不忍用刑者曰「得黄金」，用赎刑也。古者金作赎刑，如吕刑五刑之赎皆有罚，以千锾为差是也。九四以刚噬，六五以柔噬。以刚噬者，冇司执法之公；以柔噬者，人君不忍之仁也。然犹贞厉则无咎。贞厉，谨惧也。正如穆王训夏赎刑，刑既轻矣，犹曰「朕言多惧」是也。象曰「得当也」，言以柔用狱，得用狱之当也者，得圣人一个慈祥恻怛之心，更无穷也。</p><p>上九：何校灭耳，凶。象曰：「何校灭耳」，聪不明也。</p><p>九处卦之终，小人为恶之大者也，故灭其耳。系辞曰：善不积不足以成名，恶不积不足以灭身。小人以小善为无益而弗为也，以小恶为无伤而弗去也，故恶积而不可掩，罪大而不可解。易曰：「何校灭耳，凶。」䷕ 离下艮上</p><p>贲贲：亨，小利有攸往。彖曰：「贲，亨」，柔来而文刚，故「亨」。分刚上而文柔，故「小利有攸往」，天文也。文明以止，人文也。观乎「天文」，以察时变；观乎「人文」，以化成天下。</p><p>贲，饰也。以文为饰，物相合则必有文。人道无本不立，无文不行。君臣之交，宾主之欢，父子兄弟、夫妇之好，皆当有文以相接。礼仪三百，威仪三千，非徒为是繁缛，有本者固如是也。卦自泰变，阴阳往来，交错而成文，曰：「贲，亨，小利有攸往。」止得从彖解曰：柔来而文刚，故亨。上体本坤，上六一柔下来文二成离，离为文明，故亨。下体本乾，九二以刚往而文上成艮。艮，止也，故「小利有攸往」。刚柔往来，交错成文，此天文也。如日月之昼夜，阴阳之寒暑，百谷草木之荣椹，皆相错而后成文，此自然之文也，故曰「天文」。以六爻之象言也。以人道言之，则离义取明，艮义取止。文明以止，人文也。六爻之义，上下贵相文。五居君位，以上文下，吉而有喜，是文明以亨也。初二、三四，臣位也，以下文上，则不可遽进，文明以止也，「小利有攸往」之义也。此人事，故曰「人文」也。贲亨属五爻，「小利有攸往」属下四爻。盖君以礼遇臣，君臣会遇，无往不亨。士之在下，自文其身，以待上求，非其礼物之至，则不轻售，安可以骤进哉？皆不往而止，以上来成离、下往成艮为义也。曰：观乎「天文」，以察时变；观乎「人文」，以化成天下。日月星辰，往来运行，天文也，而时变系焉。君臣、父子、夫妇、朋友相接之礼，人文也，而教化系焉。人文既备，则天下化成矣。</p><p>象曰：山下有火，贲，君子以明庶政，无敢折狱。</p><p>山下有火，野烧之火也。焚薙榛棘，然后草木敷畅，物得其贲，所以为文。君子体此以明庶政，无敢折狱，礼乐明备，百度修举，所以饰国也。狱贵情实，无所用文，故不敢以文折狱。</p><p>初九，贲其趾，舍车而徒。象曰：「舍车而徒」，义弗乘也。下四爻皆取自文其身，不遽往为义。初居最下，趾之象也。趾所以行，自贲其所行也。所乐在我，无用乘人之车也，故宁舍之而徒也。象曰「义弗乘也」，以义为重，前车后乘，繋马千驷，不足贵也。</p><p>六二，贲其须。象曰：「贲其须」，与上兴也。</p><p>二居中，离体文明，道德积中，达于面目，所谓仁义礼智根于心，其生色粹然见于面者也。其所贲，与初爻贲其一体者异矣。象曰「与上兴也」，言五自上而求贲，则可与兴起，然不先往也。九三，贲如濡如，永贞吉。象曰：「永贞」之「吉」，终莫之陵也。濡，润泽也。文明之极，其德之盛，足以润其身也，故「贲如」又「濡如」，清明在躬，志气如神者也。又与「贲其须」者异矣，然亦未可进也，故曰「永贞吉」。象曰「终莫之陵也」，言终当大用也。</p><p>六四，贲如皤如，自马翰如，匪寇婚媾。象曰：六四当位疑也；「匪寇婚媾」，终无尤也。</p><p>四在三上，贲盛于三，蓄德老成，可为典型者也，故曰「贲如皤如，华发黄耇」之象也。「自马翰如」，其马亦洁白班翰而不进，不轻屈于人，所谓「皎皎白驹，在彼空谷」者也。「匪寇婚媾」，非礼而来，皆寇我者之人也，安可以寇得哉！婚媾则往矣，言备礼也。正如黄绮诸公，不肯为嫚骂，折及吕泽之聘币，至羽翼翻然而起矣。盖自「贲其趾」以至「蓄德老成」，是惟无用，用则邦家有光矣。然六五束帛已「戋戋」然而来，天下将被润泽矣。象曰「当位疑也」，言不轻往也；曰「终无尤也」，言出处之节，无一毫瑕尤也。</p><p>六五，贲于丘园，束帛戋戋，吝，终吉。象曰：六五之「吉」，有喜也。</p><p>有老成之人在下，而五欲求之，必得所以贲之之道。礼物不可轻也，故「束帛戋戋」然至于「丘园」之下，将庶几其贲我乎？上下相贲，文明而亨，此其时也。虽然，我何以聘币为哉？三至然后翻然，故始未免吝，终则吉。象曰：六五之「吉」，冇喜也。其肯来贲，喜可知也。上九：白贲，无咎。象曰：「白贲无咎」，上得志也。</p><p>至五爻相贲，文之极也。物极则反，故上九处贲之极，又反而归于「白贲」，以质为贵也。所谓「甘受和，白受采，绘事后素」是也。曰「白贲」者，所以反礼之本者也。象曰「上得志也」，谓得其本然之志也。易道履贵素履，贲尚「白贲」，皆贵质之义。</p><p>又说：上九处卦之上而无位，刚上而止，自洁其身，非六五束帛之能贲也。箕颍之流，烟霞泉石，自是一种人物，是以白为贲者也。有道之世，如是白贲者多矣。象曰：「上得志也」，得遂其素志也。䷖ 坤下艮上</p><p>剥</p><p>剥：不利有攸往。彖曰：「剥」，剥也，柔变刚也。「不利有攸往」，小人长也。顺而止之，观象也。君子尚消息盈虚，天行也。阴阳消长，天之理也。一阴生姤，积而至五，阳将尽矣。其卦为剥，五阴剥一阳，众小人剥君子之象也。虽然，剥不尽则不复，硕果不食，生意已在其中矣，此天运之所以不穷也。曰「不利有攸往」，君子处剥，不宜往也。彖曰：「剥」，剥也，柔变刚也。五柔变一刚也。「不利有攸往」，小人长也。小人长，君子当顺受也。顺而止之，观象也。坤体顺，艮体止。顺而止之，处小人之道也。自古小人之祸，皆成于君子之争，盖争则小人必胜也。君子尚消息盈虚，天行也。「消息盈虚」，天运之自然也。有善必有恶，有君子必有小人，其天地阴阳之数欤！</p><p>象曰：山附于地，「剥」。上以厚下安宅。山夷而附于地，剥象也。然山虽夷，其下愈厚，其土依然在也。小人之剥，法度坏乱。君子德泽犹在，人心未泯，民心不摇，则天道可回矣。厚下安宅，所以固人心也。</p><p>初六，剥床以足，蔑贞凶。象曰：「剥床以足」，以灭下也。自下剥上，君子在上处床也，小人自下剥之，渐而毁也。初且剥足，意在蔑正也。象曰：以蔑下也。</p><p>六二，剥床以辨，蔑贞凶。象曰：「剥床以辨」，未有与也。二阴生剥至辨也，亦蔑贞凶。象曰：「未有与也」，言党犹未盛，且剥辨也。</p><p>六三，剥之无咎。象曰：「剥之无咎」，失上下也。</p><p>圣人未尝不开小人为善之门，一阳在上，君子也；三与上正应己，小人也。处群小人之中，自异而应上，圣人许之曰「剥之无咎」。象曰「失上下也」，言失上下四阴而应上九也。</p><p>六四，剥床以肤，凶。象曰：「剥床以肤」，切近灾也。</p><p>四阴生床，剥尽而及肤矣，是君子之身已被其伤矣，故曰「切近灾也」。不言「蔑贞」者，盖四阴生，小人之道已盛，而为君子者犹不能见几而去，则非蔑贞之罪也。</p><p>六五，贯鱼，以宫人宠，无不利。象曰：「以宫人宠」，终无尤也。五阴在下，牵连而进，如贯鱼然。自古小人之乱，皆由人主委以大兵大权，故其势得以害君子。若以阉人扫除之职主之，则无不宜矣。五为君位，故言所以待小人之道。</p><p>上九，硕果不食，君子得舆，小人剥庐。象曰：「君子得舆」，民所载也。「小人剥庐」，终不可用也。</p><p>剥而至此，阳将尽矣，剥尽则复阳未尝绝也。人之食果，以渐而剥，必留一硕大者不剥，其所以不剥而食者，留以为种子。此大者剥下，生意已存于不食之中，故剥卦赖乎此阳，剥尽遂反为复，以喻君子之不可尽剥也。君子得舆，小人剥庐：在下而载其上，小人之事。一阳在上，众阴自下载之，有「君子得舆」之象。庐居上而庇其下，君子之事，一阳在上，而众阴自下剥之，有「小人剥庐」之象。初剥床之足，剥之不已，则剥其辨。又剥之不已，则剥其肤。至剥之极，则剥及于庐，是自剥其庐也。盖一君子在上，小人犹得所庇；君子尽去，则小人无托身之所矣。象曰：「君子得舆」，民所载也。「小人剥庐」，终不可用也。盖小人极盛，然后君子为民所属望；祸乱既极，然后知小人之不可用也。䷗ 震下坤上</p><p>复，</p><p>复，亨。出入无疾，朋来无咎。反复其道，七日来复，利有攸往。彖曰：「复，亨」。刚反。动而以顺行，是以「出入无疾，朋来无咎」。「反复其道，七日来复」，天行也。「利有攸往」，刚长也。复，其见天地之心乎？</p><p>序卦：「物不可以终尽，剥穷上反下，故受之以复。」物无剥尽之理，故剥极则复来，阴极则阳生。阳剥于上而复生于下，穷上而反下也。卦，一阳生五阴之下，阴极而阳复也。阳，君子之道。阳消极而复反；君子之道，消极而复长也，故为反善之义。曰「复，亨」，阳道长矣，是以「亨」也。阳长而出，阴消而入，顺消息盈虚之理，无相疾害。一阳方动，众阳从之，以类而升，何咎之有？「反复其道，七日来复」。谓消长之道，反复迭至。阳之消，至七日而来复。姤，阳之始消者也，七变而成复，故云七日，谓七更也。阳进则阴退，君子道长，小人道消，故「利有攸往」。彖：刚反，动而以顺行。阳反于下，下体为震，震，动也。上体为坤，坤，顺也。阳动于下，上体皆坤，以顺而长也，是以无疾。曰「七日来复，天行也。」盖阴阳消长，天运自然也。曰：利有攸往，刚长也。一阳来复，以渐而长，是君子道长也。复，其见天地之心乎？一阳生于下，乃天地生物之心也。夫穷冬积阴之时，天地几于无生意矣，而阳气已动于黄泉之下，犹之人焉，方其物欲之深也，几于无天理矣，而性善之端，要不可泯也，必有时而发。就其发处而观之，则天地之心见矣。程氏曰：「先儒以静见天地之心，盖不知动乃见天地之心，非知道者，孰能识之？」象曰：雷在地中，复。先王以至日闭关，商旅不行，后不省方。</p><p>阳气相搏而成雷，雷以十月闭蛰，十一月一阳生。阳气已动于地下，是雷已动而未发。雷动于地，阳复于下之象也。雷动于冬而春发声，阳复于冬而春发生，虽其气尚微，「先王以至日闭关，商旅不行，后不省方」，恐其践履阳气也。圣人辅相天地之道也。</p><p>初九，不远复，无祗悔，元吉。象曰：「不远」之复，以修身也。一阳在下，天地之心，性善之端也，故六爻以复善为义。初，复之始，始而知复，知善未远，不远复也，故不至悔而元吉。象曰：「以修身也」，学者宜以此修身也。系辞曰：「君子知微知彰，万夫之望。」子曰：「颜氏之子，其殆庶几乎！有不善未尝不知，知之未尝复行也。」易曰：「不远复，无祗悔，元吉。」</p><p>六二，休复，吉。象曰：「休复」之吉，以下仁也。</p><p>休，善也。二取初近，从善而复也，故「吉」。象曰「以下仁也」，「仁」，人心也。善端之发，莫切于仁，初复于仁而二下之也。</p><p>六三：频复，厉无咎。象曰：「频复」之厉，义「无咎」也。</p><p>三不正而位危，又取初远，屡失而屡复也。屡失故厉，屡复故「无咎」，过而复之也。</p><p>六四：中行独复。象曰：「中行独复」，以从道也。</p><p>四处五阴之中，取初虽远，而独与初应，以道自复者也。初曰「以修身」，二曰「以下仁」，四曰「以从道」，盖修身以道，修身以仁，无二理也。</p><p>六五：敦复，无悔。象曰：「敦复无悔」，中以自考也。</p><p>五居上体纯坤，天性之至厚者也。虽取初远而以性复中以自考，言反求于己，不因人而复也。</p><p>上六：迷复，凶，有灾眚。用行师，终有大败，以其国君凶，至于十年不克征。象曰：「迷复」之凶，反君道也。</p><p>上取初远，物欲之深，迷而不知复者也。妄动固有灾眚，好大喜功，败而不悟，至于十年不克征，其秦皇、汉武之所为乎？故象曰：「反君道也。」䷘ 震下乾上 无妄，</p><p>无妄：元亨，利、贞。其匪正有眚，不利有攸往。彖曰：无妄，刚自外来而为主于内。动而健，刚中而应，大亨以正，天之命也。「其匪正有眚，不利有攸往」，「无妄」之往，何之矣？天命不祐，行矣哉？</p><p>程氏曰：无妄，序卦：复则不妄矣，故受之以无妄。复者，反于道也。既复于道，则合于正理而无妄，故复之后受之以无妄也。为卦乾上震下。震，动也。动以天为无妄，动以人欲则妄矣。「无妄」，圣人可也。学者未敢言无妄，且自不妄入也。故由不妄以至无妄，所谓自明而诚也。如司马温公教学者以诚，又未敢言无妄，且自不妄语入，是又略下教人也。曰：无妄，元亨、利、贞，大亨以正，无妄之理也。初、二、四、五爻得之。其匪正有眚，不利有攸往。其处不正则妄矣，故有灾眚，而「不利有攸往」。三与上当之。彖曰：刚自外来而为主于内。一阳自卦之外来，居内卦之下，变坤为震，遂成无妄。盖无妄，实理也。天地人同就太虚中禀得，天地得之以为天，地人得之以为人，非有附丽而来也。与他卦之变不同，故曰「自外来」。故初爻为无妄之主，而六爻惟初得「吉」。盖初动之始，无一毫私意，全「无妄」之体者也。动而健，刚中而应，震动而乾健，五刚得中，二阴又得中而相应，无妄之义也。大亨以正，天之命也。无妄，诚也。诚者，天之道也。元亨利贞，天德之全也。无妄则与天为一，而天德纯全，故曰「天之命」也。子思于中庸首篇便曰：「天命之谓性。」盖本诸此。其匪正有眚，不利有攸往。无妄之往，何之矣？天命不祐，行矣哉！此释上卦辞也。言无妄之往，何往而不可？若有眚，则天命不祐，何行哉？言有眚则「不利有攸往」也。</p><p>象曰：天下雷行，物与无妄；先王以茂对时，育万物。天下雷行，万物肃然而听命，其心至一也。天与万物未尝相误，故曰「物与无妄」。圣人充此心，勿忘勿助，茂对时，育万物，全是顺天理。</p><p>初九，无妄，往吉。象曰：「无妄」之往，得志也。</p><p>一阳自外来，居无妄之初，成卦由之，动以应乾，其动以天，无妄之至也，故「往吉」，象曰「得志也」。以理而动，无往不可，其心泰然矣。</p><p>六二，不耕获，不菑畬，则利有攸往。象曰：「不耕获」，未富也。无妄，诚也，实理也，尽人物之性于己也，有一毫求得于外心，便害无妄之体。耕而获菑畬，求得于外也，必无耕获菑畬之心，然后可以有所往。二以阴居阴，虽得中，然未实也。中未实则必外求，因有此戒，故象曰「未富也」。樊迟之学稼，许子之并耕，皆耕获菑畬者也。</p><p>六三，无妄之灾，或繋之牛，行人之得，邑人之灾。象曰：「行人」得牛，邑人灾也。</p><p>以六居三，其位不正，处动之极，动而得灾。然无妄得灾，非己致也。不言悔吝，盖无妄而灾眚至，皆吾进德之验也。有一毫咎人之心，则妄矣。九四：可贞，无咎。象曰：「可贞，无咎」，固有之也。</p><p>九四，心位也。咸卦可见本然之心，无一毫之妄也。存得本然之心，则天理见矣，故曰「可贞，无咎」，言此心可贞，守之而「无咎」也。象曰「固有之也」，言此心固有，非外铄我也。</p><p>九五：无妄之疾，勿药有喜。象曰：无妄之药，不可试也。五居乾体而得中，纯乎天理，而与天为一者也，必至此而后可以言命。「无妄」不宜疾也，而得疾则天也，故可以勿药而有喜。如子疾病，子路请祷，子曰：「丘之祷久矣。」伯牛有疾，子曰：「亡之，命矣夫！」如夫子、伯牛之得疾，然后谓之「无妄之疾」。圣贤平时陟降，无非对越上帝时也，疾何用祷哉？妄而得疾，药亦无及矣。故象曰：「无妄之药，不可试也。」</p><p>上九：无妄，行有眚，无攸利。象曰：「无妄」之「行」，穷之灾也。处卦之终，其位不正，所谓匪正有眚者也。西溪易说卷五。</p>',97)])])}const m=a(i,[["render",r]]);export{h as __pageData,m as default};
